test("Alt を押しながら運んでいる間、上下左右それぞれ最初に当たる相手までの距離が出る", () => {
  renderCanvas({ selection: setupSiblings() });
  drawnApart();

  // 上は `home` の上辺まで 12、左は左辺まで 150、右は右辺まで 190、下は `card` の上辺まで 66
  carryNode("badge", { x: 113, y: -12 }, "alt");

  expect(sortedFacingDistanceLabels()).toEqual(["12", "150", "190", "66"]);
});

test("Alt を押さずに運んでいる間は、距離が出ない", () => {
  renderCanvas({ selection: setupSiblings() });
  drawnApart();

  carryNode("badge", { x: 113, y: -12 });

  expect(sortedFacingDistanceLabels()).toEqual([]);
});

test("Alt を押したままでも吸い付き、離すと吸い付いた位置の座標が書かれる", () => {
  const onRepositionNode = vi.fn();
  renderCanvas({ selection: setupSiblings(), onRepositionNode });
  drawnApart();

  dragNode("badge", { x: 113, y: -12 }, "alt");

  expect(onRepositionNode).toHaveBeenCalledWith(
    "badge",
    RepositionEdit.create({
      parentName: "home",
      placement: { mode: "absolute", x: 150, y: 12 },
    }),
  );
});

test("Alt を押したままでも、揃え先との隙間の数値は変わらない", () => {
  renderCanvas({ selection: setupSiblings() });
  drawnApart();

  carryNode("badge", { x: 113, y: -12 }, "alt");

  expect(distanceLabels("snap-gap")).toEqual(["116"]);
});

test("揃え先との隙間が同じ線を出している向きには、距離を出さず隙間だけを出す", () => {
  renderCanvas({ selection: setupSiblings() });
  drawnApart();

  /*
   * 左辺が `card` の左辺（200）へ寄り、左右 200〜220・上下 72〜84 になる。下は揃え先 `card`
   * との隙間 66（docs/06-ui.md の辺のスナップ）が出ているので、距離は上 12・左 100・右 240 だけ。
   */
  carryNode("badge", { x: 60, y: -12 }, "alt");

  expect(distanceLabels("snap-gap")).toEqual(["66"]);
  expect(sortedFacingDistanceLabels()).toEqual(["100", "12", "240"]);
});

test("⌘ と Alt を一緒に押していると、吸い付かない位置から距離を測る", () => {
  renderCanvas({ selection: setupSiblings() });
  drawnApart();

  // 吸い付かないので左右 253〜273。左は 153、右は 187 になる
  carryNode("badge", { x: 113, y: -12 }, "meta+alt");

  expect(sortedFacingDistanceLabels()).toEqual(["12", "153", "187", "66"]);
  expect(distanceLabels("snap-gap")).toEqual([]);
});

test("Alt を離して動かし直すと、距離は消える", () => {
  renderCanvas({ selection: setupSiblings() });
  drawnApart();

  carryNode("badge", { x: 113, y: -12 }, "alt");
  movePointer(drawn("badge"), { x: 213, y: 88 }, "none");

  expect(sortedFacingDistanceLabels()).toEqual([]);
});

test("離すと距離は消える", () => {
  renderCanvas({ selection: setupSiblings() });
  drawnApart();

  dragNode("badge", { x: 113, y: -12 }, "alt");

  expect(sortedFacingDistanceLabels()).toEqual([]);
});

test("倍率に端数があっても、親の縁に外側から吸い付いた向きには距離を出さない", () => {
  renderCanvas({ selection: setupSiblings() });
  drawnApart();
  wheel(canvasSurface(), { x: 0, y: -100 }, "ctrl");

  // 対照。1.2 倍で親の内側にいる間は 4 向きとも出る
  carryNode("badge", { x: 97.9, y: -20 }, "alt");
  expect(sortedFacingDistanceLabels()).toEqual(["125", "158", "58", "7"]);

  /*
   * 下辺が `home` の上辺（60）へ外側から吸い付く（上辺は 48.00000000000001 で、下辺は数 ULP
   * だけ `home` の内側に入る）。下へ進むと上辺に接し、左右は `home` と縦に幅を持って重ならない
   * ので、どの向きにも距離は出ない。丸めずに比べると接した上辺を外して奥の下辺まで測り、
   * 縁を 1 本だけ見ると下辺まで突き抜ける。隙間は `marker` の上辺まで出たまま。
   */
  movePointer(drawn("badge"), { x: 197.9, y: 63.4 }, "alt");

  expect(sortedFacingDistanceLabels()).toEqual([]);
  expect(distanceLabels("snap-gap")).toEqual(["117"]);
});

test("揃え先との隙間が同じ線を出している向きには、距離を出さない", () => {
  // 左辺が Below へ寄り（-2）、揃え先 Below との隙間（上下 20〜60）が出る
  expect(
    distanceLinesAt({
      moving: Moving,
      parentBounds: Parent,
      siblings: [Below],
    }),
  ).toEqual({
    horizontal: {
      start: Option.some({
        along: SidePairs.Horizontal,
        at: 15,
        span: { min: 0, max: 50 },
      }),
      end: Option.some({
        along: SidePairs.Horizontal,
        at: 15,
        span: { min: 70, max: 200 },
      }),
    },
    vertical: {
      start: Option.some({
        along: SidePairs.Vertical,
        at: 60,
        span: { min: 0, max: 10 },
      }),
      end: Option.none,
    },
  });
});

test("揃え先より近い兄弟がいる向きには、距離を出す", () => {
  // Below との隙間は出たまま、下へ進むと先に手前の兄弟（上下 30〜40）に当たる
  const nearer = { left: 60, top: 30, width: 30, height: 10 };

  expect(
    distanceLinesAt({
      moving: Moving,
      parentBounds: Parent,
      siblings: [Below, nearer],
    }).vertical.end,
  ).toEqual(
    Option.some({
      along: SidePairs.Vertical,
      at: 65,
      span: { min: 20, max: 30 },
    }),
  );
});

test("親の縁との隙間が同じ線を出している向きにも、距離を出さない", () => {
  /*
   * 親の下（外）にいて、左辺が親の左辺へ寄る（-0.9）。揃え先との隙間は親の下辺との間（上下
   * 100.8〜110）に出て、上へ進んだ距離も親の下辺に当たって同じ線になる。親の座標に端数を
   * 持たせ、縁の矩形を別の式で作ると線がずれることを見る。
   */
  const parentBounds = { left: 0.1, top: 0.1, width: 200.3, height: 100.7 };
  // 右へ進むと当たる兄弟（上下 80〜130）。辺も中心線も運んでいるものから 6 より離す
  const right = { left: 40, top: 80, width: 20, height: 50 };

  const distances = distanceLinesAt({
    moving: { left: 1, top: 110, width: 20, height: 10 },
    parentBounds,
    siblings: [right],
  });

  expect(distances.vertical.start).toEqual(Option.none);
  expect(Option.isSome(distances.horizontal.end)).toBe(true);
});

test("横に測った隙間が同じ線を出している向きにも、距離を出さない", () => {
  // 上辺が右の兄弟（上下 32〜52）へ寄り（+2）、揃え先のその兄弟との隙間（左右 70〜120）が出る
  const right = { left: 120, top: 32, width: 30, height: 20 };

  const distances = distanceLinesAt({
    moving: { left: 50, top: 30, width: 20, height: 10 },
    parentBounds: Parent,
    siblings: [right],
  });

  expect(distances.horizontal.end).toEqual(Option.none);
  expect(distances.horizontal.start).toEqual(
    Option.some({
      along: SidePairs.Horizontal,
      at: 37,
      span: { min: 0, max: 50 },
    }),
  );
});

test("寄せ量に端数があっても、揃え先との隙間と同じ線の向きには距離を出さない", () => {
  /*
   * 左辺が Below の左辺へ寄る量は -0.10000000000000142。寄せたあとの矩形を隙間と別の式で
   * 作ると線の位置が数 ULP ずれ、下の距離が隙間と別の線として残る。
   */
  const distances = distanceLinesAt({
    moving: { left: 50.1, top: 10.1, width: 19.7, height: 10 },
    parentBounds: Parent,
    siblings: [Below],
  });

  expect(distances.vertical.end).toEqual(Option.none);
  expect(Option.isSome(distances.vertical.start)).toBe(true);
});

test("兄弟が無ければ、上下左右とも親の縁までの線になる", () => {
  expect(
    FacingDistances.create({
      moved: Moved,
      parentBounds: Parent,
      siblings: [],
    }),
  ).toEqual({
    horizontal: {
      start: Option.some({
        along: SidePairs.Horizontal,
        at: 45,
        span: { min: 0, max: 50 },
      }),
      end: Option.some({
        along: SidePairs.Horizontal,
        at: 45,
        span: { min: 70, max: 200 },
      }),
    },
    vertical: {
      start: Option.some({
        along: SidePairs.Vertical,
        at: 60,
        span: { min: 0, max: 40 },
      }),
      end: Option.some({
        along: SidePairs.Vertical,
        at: 60,
        span: { min: 50, max: 100 },
      }),
    },
  });
});

test("兄弟に接している向きには、兄弟も親の縁も線を引かない", () => {
  const touching = { left: 70, top: 40, width: 20, height: 10 };

  const distances = FacingDistances.create({
    moved: Moved,
    parentBounds: Parent,
    siblings: [touching],
  });

  expect(distances.horizontal.end).toEqual(Option.none);
  expect(distances.horizontal.start).toEqual(
    Option.some({
      along: SidePairs.Horizontal,
      at: 45,
      span: { min: 0, max: 50 },
    }),
  );
});

test("兄弟と親の縁が同じ距離なら、親の縁までの線になる", () => {
  // 兄弟までなら、上下に向かい合う範囲 45〜50 の中央 47.5 に引く
  const sibling = { left: 200, top: 45, width: 20, height: 20 };

  expect(
    FacingDistances.create({
      moved: Moved,
      parentBounds: Parent,
      siblings: [sibling],
    }).horizontal.end,
  ).toEqual(
    Option.some({
      along: SidePairs.Horizontal,
      at: 45,
      span: { min: 70, max: 200 },
    }),
  );
});

test("親の外にいる向きは手前の縁まで測り、奥の縁まで突き抜けない", () => {
  // 親の上（上下 -20〜-10）にいる。下へ進むと親の上辺 0 に当たり、下辺 100 までは測らない
  expect(
    FacingDistances.create({
      moved: { left: 50, top: -20, width: 20, height: 10 },
      parentBounds: Parent,
      siblings: [],
    }),
  ).toEqual({
    horizontal: { start: Option.none, end: Option.none },
    vertical: {
      start: Option.none,
      end: Option.some({
        along: SidePairs.Vertical,
        at: 60,
        span: { min: -10, max: 0 },
      }),
    },
  });
});

test("端数で数 ULP 外側から重なって見えても、親の縁に外側から接している向きには線を引かない", () => {
  // 下辺は -11.99999999999999 + 12 = 1.0658e-14 で、親の上辺 0 より数 ULP 下にある
  expect(
    FacingDistances.create({
      moved: { left: 50, top: -11.99999999999999, width: 20, height: 12 },
      parentBounds: Parent,
      siblings: [],
    }),
  ).toEqual(FacingDistances.None);
  // 1 離れていれば、親の上辺までの線を引く
  expect(
    FacingDistances.create({
      moved: { left: 50, top: -13, width: 20, height: 12 },
      parentBounds: Parent,
      siblings: [],
    }).vertical.end,
  ).toEqual(
    Option.some({
      along: SidePairs.Vertical,
      at: 60,
      span: { min: -1, max: 0 },
    }),
  );
});

test("端数で数 ULP 重なって見えても、接している相手には距離 0 で当たる", () => {
  // 右辺は 0.1 + 0.2 = 0.30000000000000004 で、相手の左辺 0.3 より先にある
  const from = { left: 0.1, top: 0, width: 0.2, height: 10 };
  const to = { left: 0.3, top: 0, width: 10, height: 10 };

  expect(Facing.firstReached(Right, { from, candidates: [to] })).toEqual(
    Option.some(to),
  );
});

test("端数で数 ULP 離れて見えても、接している兄弟の間は間隔を測らない", () => {
  // 2 つ目の左辺 0.30000000000000004 は、1 つ目の右辺 0.3 より数 ULP だけ先にある
  const first: CanvasBounds = { left: 0, top: 0, width: 0.3, height: 20 };
  const second: CanvasBounds = {
    left: 0.30000000000000004,
    top: 0,
    width: 10,
    height: 20,
  };
  const third: CanvasBounds = { left: 20.3, top: 0, width: 10, height: 20 };

  expect(
    IntervalSlot.collect([first, second, third], SidePairs.Horizontal),
  ).toEqual([
    {
      pair: SidePairs.Horizontal,
      neighbor: third,
      end: AxisEnds.End,
      interval: 10,
    },
  ]);
});

test("位置だけ違う線は等しくない", () => {
  expect(
    ThinLine.equals(
      { along: SidePairs.Vertical, at: 60, span: { min: 20, max: 60 } },
      { along: SidePairs.Vertical, at: 61, span: { min: 20, max: 60 } },
    ),
  ).toBe(false);
});

test("ドキュメント上の px へ丸めると 0 になる向きは出ない", () => {
  // 上は画面上 0.4 で丸めると 0。右は対照として出る
  render(
    <FacingDistanceOverlay
      distances={{
        horizontal: { start: Option.none, end: Option.some(RightLine) },
        vertical: {
          start: Option.some({ ...UpLine, span: { min: 39.6, max: 40 } }),
          end: Option.none,
        },
      }}
      view={SameSize}
    />,
  );

  expect(
    screen
      .queryAllByTestId("facing-distance-label")
      .map((label) => label.textContent),
  ).toEqual(["130"]);
});

test("座標を置き直す落とし方は、揃え先との隙間と同じ線を除いた距離を答える", () => {
  // 下の距離は隙間と同じ線なので除かれ、左だけが残る
  const edit = DropEdit.reposition("title", SampleRepositionTarget, {
    snap: SampleGuides,
    distanceLines: SampleDistances,
  });

  expect(DropEdit.facingDistances(edit)).toEqual({
    ...FacingDistances.None,
    horizontal: {
      start: SampleDistances.horizontal.start,
      end: Option.none,
    },
  });
});

test("Alt / Option が押されていれば押下として扱う", () => {
  expect(AltKey.isHeld({ altKey: true })).toBe(true);
});

test("端数で数 ULP 重なって見えても、接している相手には距離 0 で当たる", () => {
  // 右辺は 0.1 + 0.2 = 0.30000000000000004 で、相手の左辺 0.3 より先にある
  const from = { left: 0.1, top: 0, width: 0.2, height: 10 };
  const to = { left: 0.3, top: 0, width: 10, height: 10 };

  expect(Facing.firstReached(Right, { from, candidates: [to] })).toEqual(
    Option.some(to),
  );
});

create({
  moved,
  parentBounds,
  siblings,
}: Readonly<{
  moved: CanvasBounds;
  parentBounds: CanvasBounds;
  siblings: readonly CanvasBounds[];
}>): FacingDistances {
  return FacingDistances.fromFacings((facing) => {
    // 親の縁を手前・奥の両方とも候補にする。向きの側の縁だけにすると、外側から縁に
    // 接したときにその縁を突き抜けて奥の縁まで測る
    const edges = SidePair.sides(facing.pair).map((side) =>
      CanvasBounds.sideBounds(parentBounds, side),
    );
    const candidates = [...edges, ...siblings];
    return Option.flatMap(
      Facing.firstReached(facing, { from: moved, candidates }),
      (to) => Facing.shortLineTo(facing, { from: moved, to }),
    );
  });
},
